//! Derive-generated `Display`, `Error`, `source`, and `From` impls consumed through `?`.

use thiserror::Error;

/// Leaf error generated by the error-derive crate.
#[derive(Debug, Error)]
#[error("io layer failed while reading {path}")]
pub struct IoLayer {
    pub path: String,
}

/// Parse failure with an explicit source chain link.
#[derive(Debug, Error)]
#[error("parse layer rejected token `{token}`")]
pub struct ParseLayer {
    pub token: String,
    #[source]
    pub cause: IoLayer,
}

/// Application error boundary selecting conversion edges through `?`.
#[derive(Debug, Error)]
pub enum AppError {
    /// `#[from]` generates the `From<IoLayer>` conversion edge.
    #[error("application io failure")]
    Io(#[from] IoLayer),
    /// `#[from]` generates the `From<ParseLayer>` conversion edge.
    #[error("application parse failure")]
    Parse(#[from] ParseLayer),
}

/// Service boundary that type-erases the derived application error.
#[derive(Debug, Error)]
#[error("service rejected request")]
pub struct ServiceError {
    #[source]
    source: AppError,
}

impl ServiceError {
    /// Wraps a derived application error at the service boundary.
    pub fn from_app(source: AppError) -> Self {
        Self { source }
    }
}

fn read_layer(path: &str) -> Result<(), IoLayer> {
    Err(IoLayer {
        path: path.to_owned(),
    })
}

fn parse_layer(path: &str, token: &str) -> Result<(), ParseLayer> {
    Err(ParseLayer {
        token: token.to_owned(),
        cause: IoLayer {
            path: path.to_owned(),
        },
    })
}

/// Consumes typed conversions and source chains through `?`.
pub fn service_operation(path: &str, token: &str) -> Result<u32, ServiceError> {
    fn service_inner(path: &str, token: &str) -> Result<u32, AppError> {
        read_layer(path)?;
        parse_layer(path, token)?;
        Ok(1)
    }

    service_inner(path, token).map_err(ServiceError::from_app)
}

/// Summary anchor for derive-generated error coverage.
pub fn derived_error_summary() -> &'static str {
    "error_derives"
}
